{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Selegiline, a lipophilic basic tertiary amine, has absolute oral bioavailability of only 4% in healthy volunteers after a 10 mg oral dose versus IV, due to extensive first-pass metabolism; this high-transfer evidence supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Rotigotine, a related lipophilic aminotetralin, has low oral bioavailability in humans and is limited to non-oral routes; this supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "N-0437, a close rotigotine analogue, also shows low oral bioavailability in humans, requiring subcutaneous or intravenous administration; this supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Amitriptyline, a lipophilic tricyclic tertiary amine with a dimethylaminopropyl side chain, has oral bioavailability around 45% in humans, providing contradictory evidence for high F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C47"],
      "claim": "Alfentanil, an anilide piperidine opioid with a basic amine, has baseline oral bioavailability of 37% in healthy volunteers, providing contradictory evidence for high F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Amiodarone, a lipophilic basic benzofuran with a diethylaminoethoxy side chain, has oral bioavailability of about 35-65%, providing contradictory evidence for high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer reliable experimental evidence (selegiline, rotigotine, N-0437) consistently shows low oral bioavailability for lipophilic basic amines with extensive first-pass metabolism, supporting F<20%. Although amitriptyline, alfentanil, and amiodarone show higher F (30-65%), their lower transfer scores and structural differences reduce their weight. The query's dicationic ionization and likely first-pass metabolism favor low bioavailability.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the query molecule.",
    "Metabolic stability and transporter-mediated absorption/efflux of the query are unknown.",
    "Conflicting evidence from structurally related high-F drugs (amitriptyline, alfentanil, amiodarone) creates uncertainty.",
    "Some supplied records have apparent structure/identity mismatches (e.g., brexanolone record with benzyl alcohol SMILES) and were not weighted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

